import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"2.2 处理文档、表格与网页资料","description":"产出有来源、能核对、可继续使用的资料结果。","frontmatter":{"title":"2.2 处理文档、表格与网页资料","description":"产出有来源、能核对、可继续使用的资料结果。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-2/2-2.md","filePath":"delivery/stage-2/2-2.md","lastUpdated":1793859143000}'),r={name:"delivery/stage-2/2-2.md"};function o(s,e,n,d,_,c){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="_2-2-处理文档、表格与网页资料" tabindex="-1">2.2 处理文档、表格与网页资料 <a class="header-anchor" href="#_2-2-处理文档、表格与网页资料" aria-label="Permalink to &quot;2.2 处理文档、表格与网页资料&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让 Hearth 能处理文档、表格和公开网页资料，产出可以核对的结果。重点不是“能读”，而是结果有来源、能检查、能继续使用。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>支持常见文档的读取、转换和摘要，保留原始文件和页码或段落位置。</li><li>支持表格的筛选、汇总和信息提取，结果要能对照原表检查。</li><li>做公开网页研究时，记录访问时间、网址、引用位置和页面变化。</li><li>网页内容一律当作不可信资料，不执行页面里的指令，不因为页面文字扩大权限。</li><li>登录页面、验证码或需要人工判断的情况，停下来交给用户处理。</li><li>所有结果都保存为可打开的产物，并标明来源和生成时间。</li></ol>',5)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
